{
  implies!(
    (api_request_facts.disposition == Vehicle_Start_Readiness_Recovery_Supervisor::RequestDisposition::StartCandidate) &
      api_brake_facts.evidenceTrusted &
      api_power_facts.evidenceTrusted &
      (api_health_qualification != Vehicle_Start_Readiness_Recovery_Supervisor::HealthQualification::Invalid) &
      ((api_brake_facts.readyForAdmission == false) |
        (api_health_qualification == Vehicle_Start_Readiness_Recovery_Supervisor::HealthQualification::NotReady) |
        (api_power_facts.availableForSupervision == false)),
    api_authorization_to_lifecycle.decision == Vehicle_Start_Readiness_Recovery_Supervisor::StartDecision::DenyNotReady)
}

